```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::aap::caps::state_rw;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input on every call, before any other effect.
        state_rw::put("last-input", &feed_url);

        let seconds = wall_clock::now().seconds;

        // One permitted fetch. A transport failure is a value, not a trap,
        // so it yields fetched = 0 and the run continues.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!("heartbeat at {seconds}: fetched {fetched} characters");
        let accepted = notifier::notify(&message);

        // The ensures clause requires notified == true on every output, so a
        // refused notification must not produce a report. Trap instead.
        if !accepted {
            panic!("notifier refused heartbeat; cannot produce notified == true");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified: true,
        }
    }
}

export!(Node);
```

